/**
 * 改造自 shadcn 原装 base-lyra card（https://ui.shadcn.com/r/styles/base-lyra/card.json，MIT）。
 * 与上游的差异：
 * 1. 圆角改用品牌层的圆角令牌（ADR 0024）：卡片 `rounded-surface`，CardHeader 与 CardFooter 的
 *    `rounded-none` 改成 `rounded-t-surface` 与 `rounded-b-surface`（与 shadcn 其它风格的写法一致，页眉页脚加底色时贴合外框）。
 *    缺省 `--brand-radius` 是 0，这些类都算出 0，与上游的 `rounded-none` 相同。
 *    首尾图片的 `rounded-none` 保留：卡片的 `overflow-hidden` 已经裁出圆角。
 * 2. 删掉 `CardTitle` 上的 `cn-font-heading`：它是 shadcn 的标题字体标记，本系统不用标题字体（ADR 0004），也没有定义它。
 * 此外只有格式化与 Biome 豁免注释，其余类名逐字保留。
 */
import { cn } from "cn";
import type * as React from "react";

function Card({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"div"> & { size?: "default" | "sm" }) {
  return (
    <div
      data-slot="card"
      data-size={size}
      className={cn(
        // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的卡片内边距变量（default 16px，sm 12px）。
        "group/card flex flex-col gap-(--card-spacing) overflow-hidden rounded-surface bg-card py-(--card-spacing) text-xs/relaxed text-card-foreground ring-1 ring-foreground/10 [--card-spacing:--spacing(4)] has-data-[slot=card-footer]:pb-0 has-[>img:first-child]:pt-0 data-[size=sm]:[--card-spacing:--spacing(3)] data-[size=sm]:has-data-[slot=card-footer]:pb-0 *:[img:first-child]:rounded-none *:[img:last-child]:rounded-none",
        className,
      )}
      {...props}
    />
  );
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的网格（有 CardAction 时两列，有描述时两行）。
        "group/card-header @container/card-header grid auto-rows-min items-start gap-1 rounded-t-surface px-(--card-spacing) has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto] [.border-b]:pb-(--card-spacing)",
        className,
      )}
      {...props}
    />
  );
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-title"
      className={cn("text-sm font-medium group-data-[size=sm]/card:text-sm", className)}
      {...props}
    />
  );
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-xs/relaxed text-muted-foreground", className)}
      {...props}
    />
  );
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div data-slot="card-content" className={cn("px-(--card-spacing)", className)} {...props} />
  );
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn("flex items-center rounded-b-surface border-t p-(--card-spacing)", className)}
      {...props}
    />
  );
}

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };
